My solution (Time: 41 ms (80.55%), Space: 17.7 MB (35.80%) - LeetHub)

class Solution:
    def isBalanced(self, root: Optional[TreeNode]) -> bool:

        res = True

        def dfs(root):
            nonlocal res 
            if not root:
                return 0

            left = dfs(root.left)
            right = dfs(root.right)

            if abs(left - right) > 1:
                res = False

            return 1 + max(left, right)

        dfs(root)
        return res

