class Solution:
    def lengthOfLongestSubstring(self, s: str) -> int:
        array = []
        max_size = 0

        for i in range(len(s)):
            while s[i] in array:
                array.pop(0)
            array.append(s[i])

            max_size = max(max_size, len(array))

        return max_size

