"""
The way we can solve this question is by creating a data structure called "TrieNode" with two attributes -- children and end. children detonoes a map of maps where we would put each our letters and as we reach the end of the word, we mark that letter as ending using the "end" attribute
"""

# Create a class to store the letters in form of a tree
class TrieNode:
    def __init__(self):
        self.children = {}
        self.end = False

class Trie:
    def __init__(self):
        # Initialize the TrieNode instance
        self.root = TrieNode()

    def insert(self, word: str) -> None:
        # Set the current pointer to the root of the tree
        curr = self.root

        # Go through each letter in the word and add that into the tree if not already
        for letter in word:
            if letter not in curr.children:
                curr.children[letter] = TrieNode()
            curr = curr.children[letter]

        # Since by this time, we reach the end of the word so mark the letter as end
        curr.end = True

    def search(self, word: str) -> bool:
        # Set the current pointer to the root of the tree
        curr = self.root

        # Go through each letter and keep going down in the tree to find if this word has been
        # created
        for letter in word:
            if letter not in curr.children:
                return False
            curr = curr.children[letter]

        # If at the end we have the letter marked as end then yes it exists
        return curr.end

    def startsWith(self, prefix: str) -> bool:
        # Set the current pointer to the root of the tree
        curr = self.root

        # Go through each letter and keep going down in the tree to find if this word has been
        # created
        for letter in prefix:
            if letter not in curr.children:
                return False
            curr = curr.children[letter]

        # if we never returned false, means this is the prefix or the entire word
        return True

