This is my solution if anyone is interested. More concise and it makes a lot more sense to me conceptually:

class Solution:
    def checkInclusion(self, s1: str, s2: str) -> bool:
        s1Count = [0] * 26
        s2Count = [0] * 26

        for c in s1:
            s1Count[ord(c) - ord("a")] += 1

        # Size of window is length of s1
        for i in range(len(s2)):
            s2Count[ord(s2[i]) - ord("a")] += 1
            if i >= len(s1):
                indexOfCharToRemove = i - len(s1)
                s2Count[ord(s2[indexOfCharToRemove]) - ord("a")] -= 1
            if s1Count == s2Count:
                return True
        return False

