import random

def get_choices():
    player_choice = input("Enter a choice (rock, paper, scissors, lizard, spock:)")
    options = ["rock","paper","scissors", "lizard", "spock"]
    computer_choice = random.choice(options)
    choices = {"player": player_choice,"computer": computer_choice}

    return choices
def check_win(player, computer):
    print(f"you choice was {player} and computer's choice is {computer}") 
    if player == computer:
        return  "it's a tie!" + "try again!"
    elif (player == "rock" and (computer == "scissors" or computer == "lizard")):
        return "Rock crushes Scissors or Lizard. You won!"
    elif (player == "paper" and (computer == "rock" or computer == "spock")):
        return "Paper covers Rock or disproves Spock. You won!"
    elif (player == "scissors" and (computer == "paper" or computer == "lizard")):
        return "Scissors cuts Paper or decapitates Lizard. You won!"
    elif (player == "lizard" and (computer == "paper" or computer == "spock")):
        return "Lizard eats Paper or poisons Spock. You won!"
    elif (player == "spock" and (computer == "rock" or computer == "scissors")):
        return "Spock vaporizes Rock or smashes Scissors. You won!"
    else:
        return f"{computer.capitalize()} beats {player}. You lost!"
