import java.math.BigInteger

fun reduceFraction(numerator: Int, denominator: Int): String {
    val gcd = BigInteger.valueOf(numerator.toLong()).gcd(BigInteger.valueOf(denominator.toLong()))
    val reducedNumerator = numerator / gcd.toInt()
    val reducedDenominator = denominator / gcd.toInt()

    return "$reducedNumerator/$reducedDenominator"
}

