I think of it like this:

if mid > than R, everything left of mid is sorted
if mid < than R, everything right of mid is sorted

Check if target would fall into the range of the sorted part, and if so move the L or R pointer to binary search that segment. Otherwise move to the unsorted segment and repeat:

def search(nums: List[int], target: int) -> int:
    l, r = 0, len(nums) - 1
    while l <= r:
        mid = (l + r) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] < nums[r]:
            if nums[mid + 1] <= target <= nums[r]:
                l = mid + 1
            else:
                r = mid - 1
        else:
            if nums[l] <= target <= nums[mid - 1]:
                r = mid - 1
            else:
                l = mid + 1
    return -1

EDIT: I see that multiple people came up with this version already ð

Another solution I came up with is using a modified version of binary search to locate the pivot index. Then check if the target falls into the right of left side of the pivot and use binary search on that segment.

def binary_search(nums, target, l, r):
    while l <= r:
        mid = (l + r) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] > target:
            r -= 1
        else:
            l += 1
    return -1


def find_pivot(nums, target):
    l, r = 0, len(nums) - 1
    if len(nums) == 1:
        return 0 if nums[0] == target else -1
    while nums[l] != nums[r]:
        pivot = (l + r) // 2
        if nums[pivot] > nums[r]:
            if l == pivot:
                break
            l = pivot
        else:
            r = pivot
    if nums[pivot] == target:
        return pivot
    if nums[pivot + 1] <= target <= nums[-1]:
        return binary_search(nums, target, pivot + 1, len(nums) - 1)
    else:
        return binary_search(nums, target, 0, pivot - 1)

Recursive solution using mergeSort:

class Solution:
    def mergeKLists(self, lists: List[Optional[ListNode]]) -> Optional[ListNode]:
        if not lists:
            return None
        return self.merge_sort(lists)[0]

    def merge_sort(self, nodes):
        if len(nodes) == 1:
            return nodes

        # print(nodes)
        middle = len(nodes) // 2
        nodes_left = self.merge_sort(nodes[0: middle])
        nodes_right = self.merge_sort(nodes[middle: len(nodes)])

        return self.merge(nodes_left[0], nodes_right[0])

    def merge(self, nodes_left, nodes_right):
        head = ListNode(-1)
        tail = head
        while nodes_left and nodes_right:
            if nodes_left.val <= nodes_right.val:
                tail.next = nodes_left
                tail = tail.next
                nodes_left = nodes_left.next
            else:
                tail.next = nodes_right
                tail = tail.next
                nodes_right = nodes_right.next

        tail.next = nodes_left if nodes_left else nodes_right
        return [head.next]

