class Solution:
    def subarraySum(self, nums: List[int], k: int) -> int:
        prefix_sum = {}
        return_val = 0
        prefix_sum[0] = 1
        count = 0
        for i in nums:
            count += i
            prefix = count - k
            if prefix in prefix_sum:
                return_val += prefix_sum[prefix]

            if count in prefix_sum:
                prefix_sum[count] += 1
            else:
                prefix_sum[count] = 1

        return return_val

