class MinStack:

    def __init__(self):
        self.stack = []
        self.min = math.inf

    def push(self, val: int) -> None:
        if val<self.min:
            self.min = val    
        self.stack.append((val, self.min))

    def pop(self) -> None:
        self.stack.pop()
        self.min = math.inf if not self.stack \
            else self.stack[-1][-1]

    def top(self) -> int:
        return self.stack[-1][0]

    def getMin(self) -> int:
        return self.stack[-1][1]

