This is written in Typescript.

function numDecodings(s: string): number {
    // We only care about the two previous values. The prev is initialized to 1 because for the first iteration there is always one possible combination.
    let prev = 1, prevPrev = 0;
    for (let i = s.length -1; i >= 0; i--){
        if (s[i] === '0') {
            // Our current prev will be now two position behind, so it will becode prevPrev and in this case, our prev becomes 0.
            [prev, prevPrev] = [0, prev];
        } else {
            if (i + 1 < s.length && (s[i] === '1' || (s[i] === '2' && '0123456'.includes(s[i + 1]))) ) {
                // If the current values is 1[0123456789] or 2[0123456] and we are in the array boundaries we know that there will be + prevPrev possible combinations for our current value
                [prev, prevPrev] = [prev + prevPrev, prev];   
            } else {
                // Only represent that the prev is now two steps behind. This can also be represented like this [prev, prevPrev] = [prev, prev]
                prevPrev = prev;
            }
        }
    }
    return prev;
};

