def isPalindrome(self, s: str) -> bool:
        s = s.lower()
        res = []
        for c in s:
            if c.isalnum():
                res.append(c)
        s = ''.join(res)

        return True if s == ''.join(reversed(s)) else False


And:

def isPalindrome(self, s: str) -> bool:
        s = s.lower()
        l, r = 0 , len(s)-1

        while l <= r:
            if s[l] == s[r]:
                l += 1
                r -= 1
                continue
            if not s[l].isalnum():
                l += 1
                continue
            if not s[r].isalnum():
                r -= 1
                continue
            if s[l] != s[r]:
                return False

        return True

