class Ball {
  constructor(x, y, sx, sy) {
    this.x = x;
    this.y = y;
    this.sx = sx;
    this.sy = sy;
    this.d = 20;
  }
  move() {
    this.x += this.sx;
    this.y += this.sy;
  }
  bounce() {
    if (this.x < this.d / 2 || this.x > width - this.d / 2) {
      this.sx *= -slowdown; 
     this.x=constrain(this.x,this.d/2,width-this.d/2); // correct the Position
    }
    if (this.y < this.d / 2 || this.y > height - this.d / 2) {
      this.sy *= -slowdown; 
      this.y = constrain(this.y, this.d / 2, height - this.d / 2); 
    }
  }
  show() {

    fill(random(255),random(255),random(255));
    ellipse(this.x, this.y, this.d);
  }
}

