class Solution {
   public static String minWindow(String s, String t) {

       HashMap<Character, Integer> tmap = new HashMap<>();
       HashMap<Character, Integer> smap = new HashMap<>();
       for(char c : t.toCharArray()) tmap.put(c,tmap.getOrDefault(c,0)+1);
       int count  = 0;
       int startIndex = -1;
       int start = 0;
       int prevMin = Integer.MAX_VALUE;

       for(int i = 0;i<s.length();i++){

           char ch = s.charAt(i);

           if(tmap.containsKey(ch)){
               smap.put(ch,smap.getOrDefault(ch,0)+1);
               if(smap.get(ch)==tmap.get(ch)) count++;


           }
                          if(count == tmap.size()){
                   while(count == tmap.size() && start<=i){
                       char delChar  = s.charAt(start);
                       if(i-start+1<=prevMin){
                           prevMin =  i-start+1;
                           startIndex = start;
                       }

                       if(tmap.containsKey(delChar)){
                           smap.put(delChar,smap.get(delChar)-1);
                           if(smap.get(delChar)<tmap.get(delChar)) count--;
                       }
                       start++;
                   }
               }
       }

       if(startIndex==-1) return "";
       return s.substring(startIndex,startIndex+prevMin);

   }
}

