1) Solution in kotlin without mutating the array

fun subsets(nums: IntArray): List<List<Int>> {   
        fun dfs(nums:IntArray, index: Int): List<List<Int>> {
            if (index == 0) {
                return listOf(listOf(nums.first()), listOf())
            }

            val res = dfs(nums, index - 1)
            return res + res.map { it + nums[index] }
        }
        return dfs(nums, nums.lastIndex)
    }

2) Iterative way without recursion

fun subsets(nums: IntArray): List<List<Int>> {
        val res = mutableListOf<List<Int>>()

        for (num in nums) {
            var temp = mutableListOf<List<Int>>()
            for (r in res) {
                val newList = r + num
                temp.add(newList)
            }
            res.addAll(temp)
            res.add(listOf(num))
        }

        return res.apply{
            add(listOf())            
        }.toList()
    }

