var maxProfit = function(prices) {

    let smallest = prices[0];
    let amount = 0;

    for(let i = 1; i < prices.length; i++){
        smallest = Math.min(smallest, prices[i])
        amount = Math.max(amount, (prices[i] - smallest))
    }
    
    return amount;
};

