Code in Java ->
class Solution {
    public int[] productExceptSelf(int[] nums) {
        int len = nums.length;
        int res[] = new int[len];
        int prefix[] = new int[len];
        int postfix[] = new int[len];
        for(int i = 0; i < len; i++){
            if(i==0){
                prefix[i] = 1 * nums[i];
                continue;
            }
            prefix[i] = prefix[i-1] * nums[i];
        }
        for(int i = len - 1; i >= 0; i--){
            if(i==len-1){
                postfix[i] = 1 * nums[i];
                continue;
            }
            postfix[i] = postfix[i+1] * nums[i];
        }
        for(int i = 0; i < len; i++){
            if(i==0){
                res[i] = postfix[i+1];
                continue;
            }
            if(i==len-1){
                res[i] = prefix[len-2];
                break;
            }
            int p1 = prefix[i-1];
            int p2 = postfix[i+1];
            res[i] = p1 * p2;
        }
        return res;
    }
}

