    def checkInclusion(self, s1: str, s2: str) -> bool:
        count=Counter(s1)
        l,r=0,len(s1)-1
        curr=Counter(s2[l:r+1])
        while r<len(s2):
            if count==curr:
                return True
            curr[s2[l]]-=1
