function StopWatch() {
    let startTime = 0;
    let stopTime = 0;
    let started = false;
    let stopped = false;
    let duration = 0;
    Object.defineProperty(this, 'duration', {
        get: function() {return duration;}
    });

    this.reset = function() {
        duration = 0;
        startTime = 0;
        stopTime = 0;
        started = false;
    };
    this.start = function() {
        if(started) {
            console.error("Stopwatch has already started");
        } else {
            startTime = Date.now();
            started = true;
            stopped = false;
        }
    }
    this.stop = function() {
        if(stopped) {
            console.error("Stopwatch has already stopped");
        } else {
            stopTime = Date.now();
            duration += (stopTime - startTime)/1000;
            started  = false;
            stopped = true;
        }
    }
}

