import java.util.*;

public class InvertedHalfPyramidwithNumbers {
    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);
        System.out.println("Enter the Number for length of Pyramid:");
        int n = sc.nextInt();
        sc.close();

        for (int i = n; i >= 1; i--) {

            for (int j = 1; j <= i; j++) {

                System.out.print(j + " ");
            }
            System.out.println();
        }
    }
}


