public static bool ContainsDuplicateUsingHashSet(int[] ints)
{
    HashSet<int> set = new HashSet<int>();

    for(int i = 0; i < ints.Length; i++)
    {
        if(set.Contains(ints[i]))
            return true;

        set.Add(ints[i]);
    }

    return false;
}

